def codes_au_minimum(stock, minimum):
    codes = []
    for code in sorted(stock):
        if stock[code] >= minimum:
            codes.append(code)
    return codes

def nom_par_id(fiches, identifiant):
    for fiche in fiches:
        if fiche["id"] == identifiant:
            return fiche["nom"]
    return None

def frequences(categories):
    comptes = {}
    for categorie in categories:
        comptes[categorie] = comptes.get(categorie, 0) + 1
    return comptes
